import * as core from './bundle-exchange-core.mjs';
import {bundleCases,bundlePages,bundleUnits,bundleUnitLabels} from './bundle-exchange-content.mjs';
import {bundleTable,canonicalExample} from './bundle-exchange-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s.charAt(0).toUpperCase()+s.slice(1);
const button=(text,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${text}</button>`;
const kindNames={'wrapped-count':'Wrapped bundles on the shelf','total-count':'Individual counters on the whole table','tens-digit':'Tens digit in the supplied numeral','tens-value':'Value of the tens place in individual counters'};
export function bundleExchangeEntry(){return `<section class="bundle-exchange-entry"><h2>Bundle Burrow: Exchange Table</h2><p>Count the seed counters, fill a frame, wrap ten, and unwrap them again. The amount stays the same.</p><a class="secondary" href="#numbers/exchange">Visit the Exchange Table</a></section>`;}
function workingControls(v){const m=v.model;return `<section class="bundle-working" id="bundle-working" tabindex="-1" aria-label="Work with this fixed collection"><h3>Move the same counters</h3><div class="bundle-actions">${button('Move one to the frame',`data-bundle-action="move" ${m.loose===0||m.frame===10?'disabled':''}`)}${button('Return one to the loose tray',`data-bundle-action="return-one" ${m.frame===0?'disabled':''}`)}${button(`Return all ${m.frame} frame counters`,`data-bundle-action="return-frame" ${m.frame===0?'disabled':''}`)}${button('Wrap these ten',`data-bundle-action="wrap" ${m.frame!==10?'disabled':''}`,true)}${button('Unwrap one ten into the frame',`data-bundle-action="unwrap" ${m.wrapped===0||m.frame!==0?'disabled':''}`)}</div><p class="bundle-guidance" id="bundle-action-guidance" tabindex="-1" role="status">${m.frame>0&&m.wrapped>0?'To unwrap a shelf bundle, return the frame counters to the loose tray first. ':''}${m.frame<10?'Only a full frame of ten can be wrapped. ':''}${m.loose===0?'There are no loose counters to move. ':''}Moving, wrapping and unwrapping keep all ${v.source.total} individual counters on this table.</p></section>`;}
function feedback(kind,h){if(!h)return '';const o=h.outcomes;const number=o.numberMatches?'The number matches.':'The number does not match yet.';const unit=o.unitMatches?'The label matches.':`Choose the label “${esc(bundleUnitLabels[h.target.unit])}”.`;let hint='';
 if(kind==='wrapped-count')hint='Count only wrapped bundles on the shelf. A full unwrapped frame is still individual counters.';
 if(kind==='total-count')hint='Include every counter: inside wrapped bundles, in the frame and in the loose tray. The grouping does not change the total.';
 if(kind==='tens-digit')hint='A digit is the single written symbol in a place; its value tells how many individual counters it stands for.';
 if(kind==='tens-value')hint='Each ten stands for ten individual counters. The value of the tens place stays the same when you regroup this collection.';
 return `<section class="bundle-feedback" id="bundle-feedback-${kind}" role="status" tabindex="-1"><p>${number} ${unit}</p><p>${hint}</p>${h.priorExposureUnknown?'<p class="tiny">Earlier encounters or checks are unknown. This is pictured practice after recovery.</p>':''}</section>`;}
function responseForm(v,kind){const d=v.case.drafts[kind],error=v.errors?.[kind],available=v.targets[kind].available;return `<form class="bundle-form" data-bundle-form="${kind}"><h3>${kindNames[kind]}</h3>${!available?'<p>No tens digit is written in this one-digit numeral. Use the supplied empty tens place below to discuss its value.</p>':''}<label for="bundle-text-${kind}">My number</label><input id="bundle-text-${kind}" data-bundle-text="${kind}" type="text" inputmode="numeric" maxlength="24" autocomplete="off" spellcheck="false" value="${esc(d.text)}" aria-describedby="bundle-hint-${kind}${error?` bundle-error-${kind}`:''}" ${error?'aria-invalid="true"':''} ${!available?'disabled':''}><label for="bundle-unit-${kind}">What does my number name?</label><select id="bundle-unit-${kind}" data-bundle-unit="${kind}" ${!available?'disabled':''}>${bundleUnits.map(u=>`<option value="${esc(u)}" ${d.unit===u?'selected':''}>${esc(bundleUnitLabels[u])}</option>`).join('')}</select><p class="tiny" id="bundle-hint-${kind}">Use digits from 0 to 99. Keep your own number and choose its label.</p>${error?`<p class="bundle-error" id="bundle-error-${kind}" role="alert" tabindex="-1">Enter a whole number from 0 to 99 using digits.</p>`:''}<div class="bundle-actions"><button type="submit" class="primary" data-bundle-check="${kind}" ${!available?'disabled':''}>Check this ${kind==='tens-digit'?'digit':kind==='tens-value'?'value':'reading'}</button></div>${feedback(kind,v.feedback[kind])}</form>`;}
function pageIntro(v){const n=v.source.total;const copy={exchange:['Count, frame, wrap, unwrap','Count the individual counters first. Move them into the frame one at a time; two rows of five make ten. Then wrap those same ten into one bundle.'],read:['Two different readings','Read the wrapped bundles on the shelf, then count the individual counters on the whole table.'],digits:['Read the supplied numeral',n<10?`The supplied numeral is ${n}. Discuss the value of the supplied empty tens place; regrouping leaves this numeral unchanged.`:`The supplied numeral is ${n}. Read its tens digit and the value of the tens place; regrouping leaves this numeral unchanged.`],keep:['Keep this arrangement','Keep your grouping and exact labels as they are; unfinished work is welcome too.']};const [heading,instruction]=copy[v.root.page];return `<section class="bundle-page-intro"><h2 id="bundle-page-title" tabindex="-1">${heading}</h2><p>${instruction}</p>${v.root.page==='digits'&&n<10?'<p>No tens digit is written in this one-digit numeral. The supplied empty tens place has zero tens, worth zero individual counters.</p>':''}</section>`;}
function exchangePage(){return `<section class="bundle-work"><p>Unwrap a bundle into an empty frame to see all ten again. Any grouping is welcome: it is the same collection.</p></section>`;}
function readPage(v){return `<section class="bundle-work"><div class="bundle-forms">${responseForm(v,'wrapped-count')}${responseForm(v,'total-count')}</div></section>`;}
function digitsPage(v){const n=v.source.total,tens=Math.floor(n/10),ones=n%10;return `<section class="bundle-work"><div class="bundle-forms">${responseForm(v,'tens-digit')}${responseForm(v,'tens-value')}</div><div class="bundle-numeral"><strong aria-label="Supplied numeral ${n}">${n}</strong><p>This written numeral names the ${n} individual counters on the table, however they are grouped.</p></div>${n<10?'<p>No tens digit is written in this one-digit numeral. The place-value table supplies an empty tens place: zero tens, worth zero individual counters. There is no need to write a leading zero.</p>':'<p>The tens digit is a written symbol. Its value counts the individual counters represented by that place. It need not match how many bundles are wrapped right now.</p>'}<table class="bundle-place-table"><caption>Supplied place-value table</caption><thead><tr><th scope="col">Tens place${n<10?' (supplied empty place)':''}</th><th scope="col">Ones place</th></tr></thead><tbody><tr><td>${tens} tens</td><td>${ones} ones</td></tr><tr><td>${tens*10} individual counters</td><td>${ones} individual counters</td></tr></tbody></table><p>Conventional description: ${tens} tens and ${ones} ones make ${n} individual counters. This readout describes the supplied numeral; the working table can use another grouping.</p></section>`;}
const modelText=m=>`${m.wrapped} wrapped tens, ${m.loose} loose ones and ${m.frame} frame ones`;
function draftList(drafts){return `<ul>${Object.entries(drafts).map(([k,d])=>`<li>${kindNames[k]}: ${d.text===''?'no number entered':`“${esc(d.text)}”`} (${esc(bundleUnitLabels[d.unit])}).</li>`).join('')}</ul>`;}
function keepPage(v){const k=v.kept;return `<section class="bundle-work"><div class="bundle-actions">${button(k?'Keep this version instead':'Keep this arrangement','data-bundle-keep',true)}</div>${k?`<section class="bundle-history"><h3 id="bundle-kept-title" tabindex="-1">Kept arrangement${JSON.stringify(k.model)!==JSON.stringify(v.model)?' — earlier work':''}</h3><p>${esc(k.source.request)}</p><p>${modelText(k.model)}; ${k.source.total} individual counters altogether.</p>${draftList(k.drafts)}${k.priorExposureUnknown?'<p>Earlier encounters or checks were unknown when kept.</p>':''}<p>This is a frozen description of the kept table; the countable working table above shows your current arrangement.</p></section>`:'<p>No arrangement kept for this collection yet.</p>'}${v.case.history.length?`<details class="bundle-history"><summary>Earlier checks for this collection (${v.case.history.length})</summary>${v.case.history.map(h=>`<section><h3>${kindNames[h.kind]}${JSON.stringify(h.model)!==JSON.stringify(v.model)?' — earlier work in another arrangement':' — recorded work'}</h3><p>${modelText(h.model)}; ${h.source.total} counters altogether. Response: “${esc(h.drafts[h.kind].text)}” (${esc(bundleUnitLabels[h.drafts[h.kind].unit])}).</p><p>Number ${h.outcomes.numberMatches?'matched':'did not match'}; label ${h.outcomes.unitMatches?'matched':'did not match'}. Pictured practice${h.priorExposureUnknown?'; prior history unknown':''}.</p></section>`).join('')}</details>`:''}</section>`;}
function helpPanel(v){const w=v.case,topic=w.helpTopic;let content='';
 if(topic==='units')content='<h3>One counter is always one</h3><p>A wrapped bundle holds ten individual counters. Its outline does not add a counter. A full frame holds ten unwrapped individual counters; it is not another bundle on the shelf.</p><p>Count the seeds themselves when reading the whole table. Count only the wrapped bundles when reading the shelf.</p>';
 if(topic==='digits')content=v.source.total<10?'<h3>An empty tens place</h3><p>This one-digit numeral has no written tens digit. The supplied empty tens place represents zero tens, worth zero individual counters. Regrouping does not change the numeral.</p>':'<h3>Digit, value and wrapped count</h3><p>Use the supplied numeral on the Digits page. Its tens digit names the conventional number of tens; the value of that place counts the individual counters those tens represent. Moving counters between the frame and tray, or unwrapping a ten, does not change that numeral.</p>';
 if(topic==='example'){const step=w.exampleStep,m=step===2?{wrapped:1,loose:6,frame:0}:step===1||step===3?{wrapped:0,loose:6,frame:10}:{wrapped:0,loose:16,frame:0};content=`<h3>A separate collection of sixteen</h3><p>Your own table stays as you left it. Advance each step when you want.</p>${bundleTable(m,{label:'Separate sixteen-counter example',total:16})}<p>${['Count sixteen individual counters. Next, count ten into the frame, leaving six loose.','Ten individual counters are in the full frame; six are outside. Together they make sixteen. Next, wrap only the ten in the frame.','One wrapped ten and six ones make sixteen individual counters. Next, unwrap the ten into the empty frame.','The same ten are unwrapped in the frame again, with six outside. There are still sixteen individual counters.'][step]}</p>${button(['Count ten into the example frame','Wrap the example ten','Unwrap the example ten','Example complete'][step],`data-bundle-example ${step===3?'disabled':''}`)}`;}
 return `<details class="bundle-help" ${topic?'open':''}><summary>Some help, if you like</summary><div class="bundle-help-options">${[['units','Counters and bundles'],['digits','Digit and value'],['example','See a separate example']].map(([id,label])=>button(label,`data-bundle-help="${id}" aria-pressed="${topic===id}"`)).join('')}</div><div class="bundle-actions">${button('Count and fill the frame together',`data-bundle-together="count" ${v.model.loose===0||v.model.frame===10?'disabled':''}`)}${button('Show another arrangement together','data-bundle-together="arrange"')}</div><p class="tiny">Together means help: filling counts the counters moved, without wrapping them. Another arrangement supplies conventional tens and loose ones for this same amount; your labels and earlier work stay as they are.</p>${topic?`<section class="bundle-help-content" id="bundle-help-content" tabindex="-1">${content}${button('Close this help','data-bundle-help=""')}</section>`:''}</details>`;
}
export function renderBundleExchange(state){const v=core.bundleView(state);if(v.unsupported)return {html:`<div class="bundle-exchange"><a href="#numbers">Back to Bundle Burrow</a><h1>Bundle Burrow: Exchange Table</h1><p>This saved exchange work uses a format this version cannot play. The original work is retained in your notes.</p><a href="#notes">Visit your notes</a><div class="bundle-actions">${button('Keep the original and start a fresh table','data-bundle-recover',true)}</div></div>`,facts:[],examples:[]};
 const pages={exchange:exchangePage,read:readPage,digits:digitsPage,keep:keepPage};const examples=[];const example=canonicalExample(v.model,v.source.total);if(example)examples.push(example);if(v.root.page==='digits'&&[13,20,27,30,42].includes(v.source.total))examples.push(`bundle:0:${Math.floor(v.source.total/10)}:${v.source.total%10}`);if(v.case.helpTopic==='example'&&v.case.exampleStep===2)examples.push('bundle:0:1:6');
 return {html:`<div class="bundle-exchange"><a class="back" href="#numbers">Back to Bundle Burrow</a><header class="bundle-head"><div><h1>Bundle Burrow</h1><p>The exchange table: new wrapping, same amount.</p></div><label class="bundle-picker" for="bundle-case">Choose a collection<select id="bundle-case">${bundleCases.map(c=>`<option value="${c.id}" ${c.id===v.source.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label></header><nav class="bundle-pages" aria-label="Exchange Table pages">${bundlePages.map(p=>button(title(p),`data-bundle-page="${p}" ${p===v.root.page?'aria-current="page"':''}`)).join('')}</nav><section class="bundle-request" aria-label="Current request"><p>${esc(v.source.request)}</p>${hearButton(v.source.request,'Hear this request')}</section>${pageIntro(v)}${bundleTable(v.model,{total:v.source.total})}${v.root.page==='exchange'?workingControls(v):`<div class="bundle-actions">${button('Change this grouping','data-bundle-page="exchange"')}</div>`}${pages[v.root.page](v)}${helpPanel(v)}<footer><p>Look, count, try, or talk it through. Every collection and page is open.</p><a href="#numbers">Explore Bundle Burrow</a><a href="#explore">Follow another curiosity</a></footer></div>`,facts:[],examples:[...new Set(examples)]};
}
export function bundleExchangeNotes(state){if(!Object.hasOwn(state,'bundleExchange'))return '';const v=core.bundleView(state);if(v.unsupported)return `<section class="panel bundle-exchange-notes"><h2>Bundle Exchange</h2><p>Unsupported saved work retained unchanged; table actions are unavailable until an explicit fresh start.</p><pre>${esc(JSON.stringify(state.bundleExchange,null,2))}</pre></section>`;
 return `<details class="panel bundle-exchange-notes"><summary>Bundle Exchange: arrangements and pictured practice</summary><p>These local records describe work with supplied quantities and visible pictures. They do not establish independent counting, numeral decoding, handwriting, place-value mastery or transfer.</p>${v.priorExposureUnknown?`<p>Earlier encounters or checks are unknown. Subsequent local work keeps that qualification.</p><details><summary>Original recovered work</summary><pre>${esc(JSON.stringify(v.root.recovered,null,2))}</pre></details>`:''}${Object.values(v.root.cases).map(w=>`<section><h3>${esc(w.source.title)}</h3><p>${modelText(w.model)}; ${w.source.total} individual counters altogether. ${w.history.length} retained checks. ${w.kept?'A frozen arrangement is kept.':'No arrangement kept.'}</p><details><summary>Exact model, raw labels, support and earlier work</summary><pre>${esc(JSON.stringify(w,null,2))}</pre></details></section>`).join('')}<a href="#numbers/exchange">Visit the Exchange Table</a></details>`;
}
export function bindBundleExchange(state,{save,render,navigate,focus}={}){const scope=document.querySelector('.bundle-exchange');if(!scope)return;const placeFocus=s=>focus?focus(s):document.querySelector(s)?.focus();
 const act=(fn,target)=>{const changed=fn();if(changed){save?.();render?.();}if(target)placeFocus(typeof target==='function'?target():target);};
 scope.querySelector('#bundle-case')?.addEventListener('change',e=>act(()=>core.chooseBundleCase(state,e.target.value),'#bundle-page-title'));
 scope.querySelectorAll('[data-bundle-page]').forEach(b=>b.onclick=()=>act(()=>core.setBundlePage(state,b.dataset.bundlePage),'#bundle-page-title'));
 const mutations={move:()=>core.moveBundleCounter(state,1),'return-one':()=>core.moveBundleCounter(state,-1),'return-frame':()=>core.returnBundleFrame(state),wrap:()=>core.wrapBundle(state),unwrap:()=>core.unwrapBundle(state)};
 scope.querySelectorAll('[data-bundle-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.bundleAction,old=core.bundleView(state).model;const count=old.frame;let moved=false;act(()=>{moved=mutations[action]();return moved;},()=>{const s=`[data-bundle-action="${action}"]`;return document.querySelector(s)?.disabled?'#bundle-working':s;});const notice=document.querySelector('#bundle-action-guidance');const messages={move:'Moved one individual counter into the frame.','return-one':'Returned one individual counter to the loose tray.','return-frame':`Returned ${count} individual counters from the frame to the loose tray.`,wrap:'Wrapped the same ten frame counters into one shelf bundle.',unwrap:'Unwrapped one shelf bundle into ten individual counters in the frame.'};if(notice)notice.textContent=(moved?messages[action]:'This move is unavailable. Use the enabled controls to make room first.')+' '+notice.textContent;});
 const clearForm=(kind,input)=>{input.removeAttribute('aria-invalid');input.setAttribute('aria-describedby',`bundle-hint-${kind}`);scope.querySelector(`#bundle-text-${kind}`)?.removeAttribute('aria-invalid');scope.querySelector(`#bundle-text-${kind}`)?.setAttribute('aria-describedby',`bundle-hint-${kind}`);scope.querySelector(`#bundle-error-${kind}`)?.remove();scope.querySelector(`#bundle-feedback-${kind}`)?.remove();};
 scope.querySelectorAll('[data-bundle-text]').forEach(input=>input.addEventListener('input',()=>{const kind=input.dataset.bundleText;if(core.setBundleText(state,kind,input.value)){save?.();clearForm(kind,input);}}));
 scope.querySelectorAll('[data-bundle-unit]').forEach(input=>input.addEventListener('change',()=>{const kind=input.dataset.bundleUnit;if(core.setBundleUnit(state,kind,input.value)){save?.();clearForm(kind,input);}}));
 scope.querySelectorAll('[data-bundle-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const kind=form.dataset.bundleForm;act(()=>core.checkBundle(state,kind),()=>core.bundleView(state).errors?.[kind]?`#bundle-error-${kind}`:`#bundle-feedback-${kind}`);}));
 scope.querySelectorAll('[data-bundle-together]').forEach(b=>b.onclick=()=>act(()=>b.dataset.bundleTogether==='count'?core.countBundleTogether(state):core.rearrangeBundleTogether(state),()=>core.bundleView(state).root.page==='exchange'?'#bundle-working':'#bundle-page-title'));
 scope.querySelectorAll('[data-bundle-help]').forEach(b=>b.onclick=()=>act(()=>core.setBundleHelp(state,b.dataset.bundleHelp||null),b.dataset.bundleHelp?'#bundle-help-content':'.bundle-help summary'));
 scope.querySelector('[data-bundle-example]')?.addEventListener('click',()=>act(()=>core.stepBundleExample(state),()=>core.bundleView(state).case.exampleStep>=3?'#bundle-help-content':'[data-bundle-example]'));
 scope.querySelector('[data-bundle-keep]')?.addEventListener('click',()=>act(()=>core.keepBundle(state),'#bundle-kept-title'));
 scope.querySelector('[data-bundle-recover]')?.addEventListener('click',()=>act(()=>core.recoverBundle(state),'#bundle-page-title'));
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(core.useBundleSupport(state,'narration'))save?.();},{capture:true}));
}
